public class ListNode
{
    public int Val;
    public ListNode Next;
    public ListNode(int val = 0, ListNode next = null)
    {
        Val = val;
        Next = next;
    }
}

public class Program
{
    public static void Main()
    {
        // Crear lista: 1 -> 2 -> 3 -> 4 -> 5
        var head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4, new ListNode(5)))));
        var result = Invertir(head);
        PrintList(result);
    }

    public static ListNode Invertir(ListNode head)
    {
        // Tu solución aquí
        return head;
    }

    public static void PrintList(ListNode node)
    {
        while (node != null)
        {
            Console.Write(node.Val + (node.Next != null ? "->" : ""));
            node = node.Next;
        }
        Console.WriteLine();
    }

    // Helper para tests: convierte lista a string
    public static string ListToString(ListNode node)
    {
        var sb = new System.Text.StringBuilder();
        while (node != null)
        {
            sb.Append(node.Val);
            if (node.Next != null) sb.Append("->");
            node = node.Next;
        }
        return sb.ToString();
    }
}

